#include <bits/stdc++.h>
using namespace std;

int n, x1, y1, x2, y2;
int distArr[1005][1005];
int answer = INT_MAX;

void bfs() {
    memset(distArr, -1, sizeof(distArr));

    queue<pair<int, int>> q;
    q.push({x1, y1});
    distArr[x1][y1] = 0;

    while (!q.empty()) {
        auto [x, y] = q.front();
        q.pop();

        if ((x == 0 && x2 == 0) || (x == n && x2 == n)) {
            answer = min(answer, distArr[x][y] + abs(y - y2));
        } else if ((y == 0 && y2 == 0) || (y == n && y2 == n)) {
            answer = min(answer, distArr[x][y] + abs(x - x2));
        } else {
            if (x == 0 || x == n) {
                if (distArr[x][0] == -1) {
                    distArr[x][0] = distArr[x][y] + y;
                    q.push({x, 0});
                }
                if (distArr[x][n] == -1) {
                    distArr[x][n] = distArr[x][y] + n - y;
                    q.push({x, n});
                }
            }

            if (y == 0 || y == n) {
                if (distArr[0][y] == -1) {
                    distArr[0][y] = distArr[x][y] + x;
                    q.push({0, y});
                }
                if (distArr[n][y] == -1) {
                    distArr[n][y] = distArr[x][y] + n - x;
                    q.push({n, y});
                }
            }
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> x1 >> y1 >> x2 >> y2;

    if ((x1 == 0 && x2 == 0) || (x1 == n && x2 == n)) {
        cout << abs(y1 - y2);
    } else if ((y1 == 0 && y2 == 0) || (y1 == n && y2 == n)) {
        cout << abs(x1 - x2);
    } else {
        bfs();
        cout << answer;
    }

    return 0;
}

